WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_material,a.id_oi,a.station_code,a.machine_code,a.production_order,a.mes_scheduling_code,a.product_code,a.material_code,a.seri,a.create_date,a.create_time,a.ma_vi_tri,a.so_luong,a.lan_cap,a.user_nv_nvl,a.ma_lo,a.ma_lo_ncc,a.status,a.bom_code,a.so_luong_can_cap,a.sl_su_dung,a.sl_con_lai,a.material_name,a.dvt,count(*) OVER() total FROM public.mes_oi_material a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.create_date BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.id_oi ILIKE '%%'||s.search_key||'%%' OR a.product_code=ANY(string_to_array(s.search_key,',')) OR a.material_code=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR EXISTS(SELECT 1 FROM public.mes_oi_confirm c WHERE c.id_oi=a.id_oi AND c.branch_code=ANY(string_to_array(s.bs,',')))) ORDER BY a.create_date DESC,a.create_time DESC,a.id_material LIMIT (SELECT lim FROM p);
